+                                                            .withMaxPartSize(
+                                                                    MemorySize.ofMebiBytes(1))
+                                                            .withRolloverInterval(
+                                                                    Duration.ofSeconds(10))
+                                                            .build())
+                                            .build()))
+                    .withName("output");
+        } else {
+            // Print the results to the STDOUT.
+            joinedStream.toSink(new WrappedSink<>(new PrintSink<>())).withName("print-sink");
+        }
+
+        // execute program
+        env.execute("Join Grade and Salary");
+    }
+
