+                    .getIdentifier()
+                    .equals(EVENT_TIME_WATERMARK_DECLARATION.getIdentifier())) {
+                // For our custom event time watermark, we can get current event time and output
+                // sales result
+                long currentEventTime = ((LongWatermark) watermark).getValue();
