+            int l = Character.digit(bytes[i], 16);
+            int r = Character.digit(bytes[i + 1], 16);
+            if (l == -1 || r == -1) {
+                return null;
+            }
+            i -= 2;
+            out[j--] = (byte) (((l << 4) | r) & 0xFF);
+        }
